import type { FitAddon } from "@xterm/addon-fit";
import type { Terminal } from "@xterm/xterm";
import { useEffect, useRef, useState } from "react";

import { isTauriRuntime, resizeTerminal, writeTerminal } from "../lib/tauri";
import { terminalEventBus } from "../lib/terminalEvents";
import { attachWebglRenderer, loadTerminalAssets } from "../lib/terminalRenderer";
import {
  applyTerminalSettings,
  fetchCachedNativePreferences,
  FALLBACK_PREFERENCES,
  loadTerminalSettings,
  resolveTerminalSettings,
  useTerminalSettings,
} from "../lib/terminalSettings";
import type { TerminalSession } from "../lib/types";

type TerminalPaneProps = {
  session: TerminalSession;
  active: boolean;
  onBell?: () => void;
  onTitleChange?: (title: string) => void;
};

export function TerminalPane({ session, active, onBell, onTitleChange }: TerminalPaneProps) {
  const hostRef = useRef<HTMLDivElement>(null);
  const terminalRef = useRef<Terminal | null>(null);
  const fitRef = useRef<FitAddon | null>(null);
  const sessionRef = useRef(session);
  const onBellRef = useRef(onBell);
  const onTitleChangeRef = useRef(onTitleChange);
  const { settings, refreshNativePreferences } = useTerminalSettings();
  const settingsRef = useRef(settings);
  const refreshPreferencesRef = useRef(refreshNativePreferences);
  const [connectionError, setConnectionError] = useState<string | null>(null);
  const [terminalReady, setTerminalReady] = useState(false);

  sessionRef.current = session;
  onBellRef.current = onBell;
  onTitleChangeRef.current = onTitleChange;
  settingsRef.current = settings;
  refreshPreferencesRef.current = refreshNativePreferences;

  useEffect(() => {
    if (active && terminalRef.current) {
      requestAnimationFrame(() => {
        fitRef.current?.fit();
        terminalRef.current?.focus();
      });
    }
  }, [active]);

  useEffect(() => {
    const terminal = terminalRef.current;
    if (!terminal) return;
    applyTerminalSettings(terminal, settings);
    requestAnimationFrame(() => fitRef.current?.fit());
  }, [
    settings.fontFamily,
    settings.fontSize,
    settings.macosOptionAsAlt,
    settings.scrollback,
    settings.cursorStyle,
    settings.theme,
  ]);

  useEffect(() => {
    const terminal = terminalRef.current;
    const backendSessionId = session.backendSessionId;
    if (!terminal || !backendSessionId) return;

    const unsubscribe = terminalEventBus.subscribeOutput(backendSessionId, (text) => {
      terminal.write(text);
    });
    return unsubscribe;
  }, [session.backendSessionId, terminalReady]);

  useEffect(() => {
    const host = hostRef.current;
    if (!host) return;

    const abortController = new AbortController();
    let disposed = false;
    let cleanupTerminal: (() => void) | null = null;
    setConnectionError(null);
    setTerminalReady(false);

    void initialize(host).catch((error: unknown) => {
      if (disposed) return;
      setConnectionError(error instanceof Error ? error.message : "Terminal renderer failed");
    });

    async function initialize(hostElement: HTMLDivElement) {
      let latestNativePrefs = await Promise.race([
        fetchCachedNativePreferences(),
        new Promise<typeof FALLBACK_PREFERENCES>((resolve) =>
          setTimeout(() => resolve(FALLBACK_PREFERENCES), 1500),
        ),
      ]);
      if (disposed) return;

      if (typeof document !== "undefined" && "fonts" in document) {
        try {
          await Promise.race([
            document.fonts.ready,
            new Promise((resolve) => setTimeout(resolve, 300)),
          ]);
        } catch {
        }
      }
      if (disposed) return;

      const finalSettings = resolveTerminalSettings(loadTerminalSettings(), latestNativePrefs);

      const { Terminal: TerminalConstructor, FitAddon: FitAddonConstructor } = await loadTerminalAssets();
      if (disposed) return;

      const terminal = new TerminalConstructor({
        allowProposedApi: false,
        customGlyphs: true,
        convertEol: true,
        cursorBlink: true,
        cursorStyle: finalSettings.cursorStyle ?? "block",
        fontFamily: finalSettings.fontFamily,
        fontSize: finalSettings.fontSize,
        lineHeight: 1.0,
        letterSpacing: 0,
        macOptionIsMeta: finalSettings.macosOptionAsAlt,
        scrollback: finalSettings.scrollback,
        theme: finalSettings.theme,
      });
      const fitAddon = new FitAddonConstructor();
      terminal.loadAddon(fitAddon);
      terminal.open(hostElement);
      terminalRef.current = terminal;
      fitRef.current = fitAddon;
      setTerminalReady(true);

      let disposeWebgl: () => void = () => undefined;
      void attachWebglRenderer(terminal, abortController.signal).then((dispose) => {
        if (disposed) {
          dispose();
          return;
        }
        disposeWebgl = dispose;
      });

      let resizeFrame = 0;
      const resize = () => {
        cancelAnimationFrame(resizeFrame);
        resizeFrame = requestAnimationFrame(() => {
          if (disposed || hostElement.clientWidth === 0 || hostElement.clientHeight === 0) return;
          fitAddon.fit();
          const backendSessionId = sessionRef.current.backendSessionId;
          if (!backendSessionId) return;
          void resizeTerminal({ sessionId: backendSessionId, cols: terminal.cols, rows: terminal.rows }).catch(() => undefined);
        });
      };

      const resizeObserver = new ResizeObserver(resize);
      resizeObserver.observe(hostElement);

      const dataDisposable = terminal.onData((data) => {
        const backendSessionId = sessionRef.current.backendSessionId;
        if (!backendSessionId) return;
        void writeTerminal({ sessionId: backendSessionId, data }).catch((error: unknown) => {
          setConnectionError(error instanceof Error ? error.message : "Terminal write failed");
        });
      });

      const bellDispose = terminal.onBell(() => onBellRef.current?.());
      const titleDispose = terminal.onTitleChange((title) => onTitleChangeRef.current?.(title));

      const focusTerminal = () => terminal.focus();
      hostElement.addEventListener("pointerdown", focusTerminal);

      if (!isTauriRuntime()) {
        terminal.writeln("\x1b[1;32mrorca\x1b[0m  UI preview");
        terminal.writeln("\x1b[90mLaunch through Tauri to attach the PTY session.\x1b[0m");
        terminal.write("\r\n\x1b[34m~\x1b[0m \x1b[32m❯\x1b[0m ");
      }

      resize();
      if (active) terminal.focus();

      cleanupTerminal = () => {
        cancelAnimationFrame(resizeFrame);
        resizeObserver.disconnect();
        hostElement.removeEventListener("pointerdown", focusTerminal);
        dataDisposable.dispose();
        bellDispose.dispose();
        titleDispose.dispose();
        disposeWebgl();
        terminal.dispose();
        terminalRef.current = null;
        fitRef.current = null;
        setTerminalReady(false);
      };
    }

    return () => {
      disposed = true;
      abortController.abort();
      cleanupTerminal?.();
    };
  }, [session.id]);

  return (
    <div className="relative h-full w-full bg-terminal">
      <div ref={hostRef} className="terminal-host h-full w-full" aria-label={`Terminal in ${session.cwd}`} />
      {connectionError ? (
        <div className="pointer-events-none absolute bottom-3 right-3 max-w-error rounded-md border border-destructive/30 bg-destructive/10 px-2 py-1 text-[11px] text-destructive">
          PTY disconnected
        </div>
      ) : null}
    </div>
  );
}

import type { FitAddon } from "@xterm/addon-fit";
import type { Terminal } from "@xterm/xterm";
import React, { useEffect, useRef, useState } from "react";
import { MobileKeyDock } from "../components/MobileKeyDock";
import { attachWebglRenderer, loadTerminalAssets } from "../lib/terminalRenderer";
import { applyTerminalSettings, useTerminalSettings } from "../lib/terminalSettings";

type RemoteTerminalProps = {
  sessionId: string;
  token: string;
  title?: string;
  onBack: () => void;
};

export const RemoteTerminal: React.FC<RemoteTerminalProps> = ({
  sessionId,
  token,
  title,
  onBack,
}) => {
  const containerRef = useRef<HTMLDivElement>(null);
  const wsRef = useRef<WebSocket | null>(null);
  const termRef = useRef<Terminal | null>(null);
  const fitRef = useRef<FitAddon | null>(null);
  const [connected, setConnected] = useState(false);
  const { settings, refreshNativePreferences } = useTerminalSettings();
  const settingsRef = useRef(settings);

  settingsRef.current = settings;

  useEffect(() => {
    void refreshNativePreferences();
  }, [refreshNativePreferences]);

  useEffect(() => {
    if (!containerRef.current) return;

    let terminalInstance: Terminal | null = null;
        let cleanupWebgl: (() => void) | null = null;
    let isDisposed = false;

    const abortController = new AbortController();

    loadTerminalAssets()
      .then(async ({ Terminal: TerminalCtor, FitAddon: FitAddonCtor }) => {
        if (isDisposed || !containerRef.current) return;

        const term = new TerminalCtor({
          cursorBlink: true,
          fontFamily: settingsRef.current.fontFamily,
          fontSize: settingsRef.current.fontSize,
          macOptionIsMeta: settingsRef.current.macosOptionAsAlt,
          scrollback: settingsRef.current.scrollback,
          cursorStyle: settingsRef.current.cursorStyle,
          theme: {
            background: settingsRef.current.theme.background,
            foreground: settingsRef.current.theme.foreground,
            cursor: settingsRef.current.theme.cursor,
            cursorAccent: settingsRef.current.theme.cursorAccent,
            selectionBackground: settingsRef.current.theme.selectionBackground,
            selectionForeground: settingsRef.current.theme.selectionForeground,
            black: settingsRef.current.theme.black,
            red: settingsRef.current.theme.red,
            green: settingsRef.current.theme.green,
            yellow: settingsRef.current.theme.yellow,
            blue: settingsRef.current.theme.blue,
            magenta: settingsRef.current.theme.magenta,
            cyan: settingsRef.current.theme.cyan,
            white: settingsRef.current.theme.white,
            brightBlack: settingsRef.current.theme.brightBlack,
            brightRed: settingsRef.current.theme.brightRed,
            brightGreen: settingsRef.current.theme.brightGreen,
            brightYellow: settingsRef.current.theme.brightYellow,
            brightBlue: settingsRef.current.theme.brightBlue,
            brightMagenta: settingsRef.current.theme.brightMagenta,
            brightCyan: settingsRef.current.theme.brightCyan,
            brightWhite: settingsRef.current.theme.brightWhite,
          },
          allowTransparency: true,
        });

        const fitAddon = new FitAddonCtor();
        term.loadAddon(fitAddon);
        term.open(containerRef.current);
        cleanupWebgl = await attachWebglRenderer(term, abortController.signal);

        fitAddon.fit();
        termRef.current = term;
        fitRef.current = fitAddon;
        terminalInstance = term;

        const protocol = window.location.protocol === "https:" ? "wss:" : "ws:";
        const wsUrl = `${protocol}//${window.location.host}/api/v1/terminal/${sessionId}?token=${encodeURIComponent(token)}`;

        const ws = new WebSocket(wsUrl);
        ws.binaryType = "arraybuffer";
        wsRef.current = ws;

        ws.onopen = () => {
          setConnected(true);
          fitAddon.fit();
          ws.send(JSON.stringify({ type: "resize", cols: term.cols, rows: term.rows }));
        };

        ws.onclose = () => {
          setConnected(false);
        };

        ws.onmessage = (event) => {
          if (typeof event.data === "string") {
            term.write(event.data);
          } else {
            term.write(new Uint8Array(event.data));
          }
        };

        term.onData((data) => {
          if (ws.readyState === WebSocket.OPEN) {
            ws.send(new TextEncoder().encode(data));
          }
        });
      })
      .catch(() => {});

    // Handle soft keyboard and viewport adaptation
    const handleViewportResize = () => {
      if (fitRef.current && wsRef.current?.readyState === WebSocket.OPEN && termRef.current) {
        fitRef.current.fit();
        wsRef.current.send(
          JSON.stringify({
            type: "resize",
            cols: termRef.current.cols,
            rows: termRef.current.rows,
          })
        );
      }
    };

    window.addEventListener("resize", handleViewportResize);
    if (window.visualViewport) {
      window.visualViewport.addEventListener("resize", handleViewportResize);
      window.visualViewport.addEventListener("scroll", handleViewportResize);
    }

    return () => {
      isDisposed = true;
      window.removeEventListener("resize", handleViewportResize);
      if (window.visualViewport) {
        window.visualViewport.removeEventListener("resize", handleViewportResize);
        window.visualViewport.removeEventListener("scroll", handleViewportResize);
      }
      if (wsRef.current) {
        wsRef.current.close();
      }
      if (cleanupWebgl) {
        cleanupWebgl();
      }
      if (terminalInstance) {
        terminalInstance.dispose();
      }
    };
  }, [sessionId, token]);

  // Synchronize settings changes dynamically (font, size, option-as-alt, theme)
  useEffect(() => {
    if (termRef.current) {
      applyTerminalSettings(termRef.current, settings);
      fitRef.current?.fit();
    }
  }, [settings]);

  const sendKey = (key: string) => {
    const ws = wsRef.current;
    if (!ws || ws.readyState !== WebSocket.OPEN) return;

    const enc = new TextEncoder();
    if (key === "ctrl-c") {
      ws.send(JSON.stringify({ type: "signal", signal: "interrupt" }));
    } else if (key === "tab") {
      ws.send(enc.encode("\t"));
    } else if (key === "esc") {
      ws.send(enc.encode("\x1b"));
    } else if (key === "up") {
      ws.send(enc.encode("\x1b[A"));
    } else if (key === "down") {
      ws.send(enc.encode("\x1b[B"));
    } else if (key === "left") {
      ws.send(enc.encode("\x1b[D"));
    } else if (key === "right") {
      ws.send(enc.encode("\x1b[C"));
    } else if (key === "ctrl-d") {
      ws.send(enc.encode("\x04"));
    } else if (key === "ctrl-z") {
      ws.send(enc.encode("\x1a"));
    } else if (key === "pageup") {
      ws.send(enc.encode("\x1b[5~"));
    } else if (key === "pagedown") {
      ws.send(enc.encode("\x1b[6~"));
    } else if (key === "home") {
      ws.send(enc.encode("\x1b[H"));
    } else if (key === "end") {
      ws.send(enc.encode("\x1b[F"));
    } else if (key.startsWith("ctrl-")) {
      const char = key.replace("ctrl-", "");
      if (char.length === 1) {
        const code = char.toUpperCase().charCodeAt(0) - 64;
        if (code >= 1 && code <= 26) {
          ws.send(new Uint8Array([code]));
        }
      }
    } else {
      ws.send(enc.encode(key));
    }
  };

  return (
    <div className="flex flex-col h-[100dvh] bg-[#0a0a0a] text-[#d4d4d4] overflow-hidden">
      {/* High-polish Orca Topbar */}
      <div className="flex justify-between items-center px-3 py-1.5 bg-[#12141a] border-b border-[#262833] shrink-0">
        <div className="flex items-center gap-2">
          <button
            type="button"
            onClick={onBack}
            className="text-xs px-2 py-1 bg-[#1a1d26] hover:bg-[#222734] text-[#c9d1d9] border border-[#2c3140] rounded font-medium transition-colors"
          >
            ← Workspace
          </button>
          <span className="font-medium text-xs text-[#fafafa] truncate max-w-[180px]">
            {title || `Terminal (${sessionId.substring(0, 8)})`}
          </span>
        </div>
        <div className="flex items-center gap-1.5">
          <span
            className={`w-2 h-2 rounded-full ${
              connected ? "bg-emerald-500 shadow-[0_0_8px_rgba(16,185,129,0.6)]" : "bg-amber-500 animate-pulse"
            }`}
          />
          <span className="text-[10px] font-mono text-[#8b949e]">
            {connected ? "Live" : "Connecting"}
          </span>
        </div>
      </div>

      {/* xterm.js Terminal Container */}
      <div ref={containerRef} className="flex-1 p-1 bg-[#0a0a0a] overflow-hidden" />

      {/* Touch-First Mobile KeyDock */}
      <MobileKeyDock onSendKey={sendKey} />
    </div>
  );
};

import type { Terminal } from "@xterm/xterm";

import {
  recordCanvasFallback,
  recordWebglContextLoss,
  recordWebglCreated,
  recordWebglDisposed,
  recordWebglLoadFailure,
} from "./terminalRendererMetrics";

export async function loadTerminalAssets() {
  const [xtermModule, fitModule] = await Promise.all([
    import("@xterm/xterm"),
    import("@xterm/addon-fit"),
    import("@xterm/xterm/css/xterm.css"),
  ]);

  return {
    Terminal: xtermModule.Terminal,
    FitAddon: fitModule.FitAddon,
  };
}

export async function attachWebglRenderer(terminal: Terminal, signal?: AbortSignal): Promise<() => void> {
  let addon: InstanceType<(typeof import("@xterm/addon-webgl"))["WebglAddon"]> | null = null;
  let tracked = false;
  let disposed = false;

  const dispose = (canvasFallback: boolean) => {
    if (disposed) return;
    disposed = true;

    try {
      addon?.dispose();
    } finally {
      if (tracked) {
        tracked = false;
        recordWebglDisposed();
      }
      if (canvasFallback) recordCanvasFallback();
    }
  };

  try {
    const { WebglAddon } = await import("@xterm/addon-webgl");
    if (signal?.aborted) return () => undefined;

    addon = new WebglAddon();
    recordWebglCreated();
    tracked = true;

    addon.onContextLoss(() => {
      if (disposed) return;
      recordWebglContextLoss();
      dispose(true);
    });

    terminal.loadAddon(addon);
    return () => dispose(false);
  } catch {
    dispose(false);
    recordWebglLoadFailure();
    recordCanvasFallback();
    return () => undefined;
  }
}

import { useCallback, useEffect, useMemo, useState } from "react";

import { getTerminalPreferences, type TerminalPreferences, type TerminalThemeColors } from "./tauri";

export type TerminalSettings = {
  fontFamily: string | null;
  macosOptionAsAlt: boolean | null;
  fontSize: number | null;
  scrollback: number;
};

export type TerminalSettingSource = "local" | "ghostty" | "fallback";

export type EffectiveTerminalSettings = {
  fontFamily: string;
  macosOptionAsAlt: boolean;
  fontSize: number;
  scrollback: number;
  cursorStyle: "bar" | "block" | "underline";
  theme: TerminalThemeColors;
  fontFamilySource: TerminalSettingSource;
  macosOptionAsAltSource: TerminalSettingSource;
  fontSizeSource: TerminalSettingSource;
};

export const TERMINAL_SETTINGS_STORAGE_KEY = "orca.terminal.settings";
export const DEFAULT_TERMINAL_SETTINGS: TerminalSettings = {
  fontFamily: null,
  macosOptionAsAlt: null,
  fontSize: null,
  scrollback: 10_000,
};

const TERMINAL_SETTINGS_EVENT = "orca:terminal-settings";
const FONT_SIZE_MIN = 10;
const FONT_SIZE_MAX = 36;
const SCROLLBACK_MIN = 1_000;
const SCROLLBACK_MAX = 100_000;

export const DEFAULT_TERMINAL_THEME: TerminalThemeColors = {
  background: "#282c34",
  foreground: "#ffffff",
  cursor: "#ffffff",
  cursorAccent: "#282c34",
  selectionBackground: "#52525299",
  black: "#1d1f21",
  red: "#cc6666",
  green: "#b5bd68",
  yellow: "#f0c674",
  blue: "#81a2be",
  magenta: "#b294bb",
  cyan: "#8abeb7",
  white: "#c5c8c6",
  brightBlack: "#666666",
  brightRed: "#d54e53",
  brightGreen: "#b9ca4a",
  brightYellow: "#e7c547",
  brightBlue: "#7aa6da",
  brightMagenta: "#c397d8",
  brightCyan: "#70c0b1",
  brightWhite: "#eaeaea",
  extendedAnsi: [],
};

export const FALLBACK_PREFERENCES: TerminalPreferences = {
  fontFamily: "monospace",
  fontSize: 13,
  macosOptionAsAlt: false,
  cursorStyle: "block",
  theme: DEFAULT_TERMINAL_THEME,
  source: "defaults",
  status: "absent",
  sourcePath: null,
};

type TerminalOptionsTarget = {
  options: {
    fontFamily?: string;
    macOptionIsMeta?: boolean;
    fontSize?: number;
    scrollback?: number;
    cursorStyle?: "bar" | "block" | "underline";
    theme?: import("@xterm/xterm").ITheme;
  };
};

export function loadTerminalSettings(storage: Pick<Storage, "getItem"> | null = browserStorage()): TerminalSettings {
  if (!storage) return DEFAULT_TERMINAL_SETTINGS;
  try {
    const raw = storage.getItem(TERMINAL_SETTINGS_STORAGE_KEY);
    if (!raw) return DEFAULT_TERMINAL_SETTINGS;
    return normalizeTerminalSettings(JSON.parse(raw) as Partial<TerminalSettings>);
  } catch {
    return DEFAULT_TERMINAL_SETTINGS;
  }
}

export function saveTerminalSettings(
  next: Partial<TerminalSettings>,
  storage: Pick<Storage, "setItem"> | null = browserStorage(),
): TerminalSettings {
  const normalized = normalizeTerminalSettings(next);
  try {
    storage?.setItem(TERMINAL_SETTINGS_STORAGE_KEY, JSON.stringify(normalized));
  } catch {
  }
  if (typeof window !== "undefined") {
    window.dispatchEvent(new CustomEvent<TerminalSettings>(TERMINAL_SETTINGS_EVENT, { detail: normalized }));
  }
  return normalized;
}

export function resolveTerminalSettings(
  local: TerminalSettings,
  nativePreferences: TerminalPreferences = FALLBACK_PREFERENCES,
): EffectiveTerminalSettings {
  const ghosttyImported = nativePreferences.source === "ghostty" && nativePreferences.status === "imported";
  const localFontFamily = normalizeOptionalFontFamily(local.fontFamily);
  const hasLocalOptionOverride = typeof local.macosOptionAsAlt === "boolean";
  const hasLocalFontSizeOverride = typeof local.fontSize === "number" && Number.isFinite(local.fontSize);

  const cursorStyle: "bar" | "block" | "underline" =
    nativePreferences.cursorStyle === "bar" || nativePreferences.cursorStyle === "underline"
      ? nativePreferences.cursorStyle
      : "block";

  const effectiveFontSize = hasLocalFontSizeOverride
    ? local.fontSize!
    : nativePreferences.fontSize ?? 13;

  return {
    fontFamily: localFontFamily ?? (nativePreferences.fontFamily || "monospace"),
    macosOptionAsAlt: hasLocalOptionOverride ? local.macosOptionAsAlt! : nativePreferences.macosOptionAsAlt,
    fontSize: effectiveFontSize,
    scrollback: local.scrollback,
    cursorStyle,
    theme: nativePreferences.theme ?? DEFAULT_TERMINAL_THEME,
    fontFamilySource: localFontFamily ? "local" : ghosttyImported ? "ghostty" : "fallback",
    macosOptionAsAltSource: hasLocalOptionOverride ? "local" : ghosttyImported ? "ghostty" : "fallback",
    fontSizeSource: hasLocalFontSizeOverride ? "local" : ghosttyImported ? "ghostty" : "fallback",
  };
}

export function applyTerminalSettings(terminal: TerminalOptionsTarget, settings: EffectiveTerminalSettings) {
  terminal.options.fontFamily = settings.fontFamily;
  terminal.options.macOptionIsMeta = settings.macosOptionAsAlt;
  terminal.options.fontSize = settings.fontSize;
  terminal.options.scrollback = settings.scrollback;
  terminal.options.cursorStyle = settings.cursorStyle;
  terminal.options.theme = {
    background: settings.theme.background,
    foreground: settings.theme.foreground,
    cursor: settings.theme.cursor,
    cursorAccent: settings.theme.cursorAccent,
    selectionBackground: settings.theme.selectionBackground,
    selectionForeground: settings.theme.selectionForeground,
    black: settings.theme.black,
    red: settings.theme.red,
    green: settings.theme.green,
    yellow: settings.theme.yellow,
    blue: settings.theme.blue,
    magenta: settings.theme.magenta,
    cyan: settings.theme.cyan,
    white: settings.theme.white,
    brightBlack: settings.theme.brightBlack,
    brightRed: settings.theme.brightRed,
    brightGreen: settings.theme.brightGreen,
    brightYellow: settings.theme.brightYellow,
    brightBlue: settings.theme.brightBlue,
    brightMagenta: settings.theme.brightMagenta,
    brightCyan: settings.theme.brightCyan,
    brightWhite: settings.theme.brightWhite,
    extendedAnsi: settings.theme.extendedAnsi,
  };
}

let globalPreferencesPromise: Promise<TerminalPreferences> | null = null;

export function resetTerminalPreferencesCache() {
  globalPreferencesPromise = null;
}

export async function fetchCachedNativePreferences(force = false): Promise<TerminalPreferences> {
  if (!globalPreferencesPromise || force) {
    globalPreferencesPromise = getTerminalPreferences().catch(() => FALLBACK_PREFERENCES);
  }
  return globalPreferencesPromise;
}

export function useTerminalSettings() {
  const [localSettings, setLocalSettings] = useState<TerminalSettings>(() => loadTerminalSettings());
  const [nativePreferences, setNativePreferences] = useState<TerminalPreferences>(FALLBACK_PREFERENCES);

  const refreshNativePreferences = useCallback(async (force = true): Promise<TerminalPreferences> => {
    const preferences = await fetchCachedNativePreferences(force);
    setNativePreferences(preferences);
    return preferences;
  }, []);

  useEffect(() => {
    void refreshNativePreferences(true);
  }, [refreshNativePreferences]);

  useEffect(() => {
    const handleSettings = (event: Event) => {
      const detail = (event as CustomEvent<TerminalSettings>).detail;
      if (detail) setLocalSettings(normalizeTerminalSettings(detail));
    };
    const handleStorage = (event: StorageEvent) => {
      if (event.key === TERMINAL_SETTINGS_STORAGE_KEY) setLocalSettings(loadTerminalSettings());
    };
    window.addEventListener(TERMINAL_SETTINGS_EVENT, handleSettings);
    window.addEventListener("storage", handleStorage);
    return () => {
      window.removeEventListener(TERMINAL_SETTINGS_EVENT, handleSettings);
      window.removeEventListener("storage", handleStorage);
    };
  }, []);

  const updateSettings = useCallback((patch: Partial<TerminalSettings>) => {
    setLocalSettings((current) => saveTerminalSettings({ ...current, ...patch }));
  }, []);

  const settings = useMemo(
    () => resolveTerminalSettings(localSettings, nativePreferences),
    [localSettings, nativePreferences],
  );

  return { settings, localSettings, nativePreferences, updateSettings, refreshNativePreferences };
}

function normalizeTerminalSettings(settings: Partial<TerminalSettings>): TerminalSettings {
  return {
    fontFamily: normalizeOptionalFontFamily(settings.fontFamily),
    macosOptionAsAlt: typeof settings.macosOptionAsAlt === "boolean" ? settings.macosOptionAsAlt : null,
    fontSize: typeof settings.fontSize === "number" && Number.isFinite(settings.fontSize)
      ? clampInteger(settings.fontSize, 13, FONT_SIZE_MIN, FONT_SIZE_MAX)
      : null,
    scrollback: clampInteger(settings.scrollback, DEFAULT_TERMINAL_SETTINGS.scrollback, SCROLLBACK_MIN, SCROLLBACK_MAX),
  };
}

function normalizeOptionalFontFamily(value: string | null | undefined) {
  if (typeof value !== "string") return null;
  const trimmed = value.trim();
  return trimmed.length > 0 ? trimmed : null;
}

function clampInteger(value: number | undefined, fallback: number, min: number, max: number) {
  if (!Number.isFinite(value)) return fallback;
  return Math.min(max, Math.max(min, Math.round(value!)));
}

function browserStorage() {
  if (typeof window === "undefined") return null;
  try {
    return window.localStorage;
  } catch {
    return null;
  }
}

import {
  ArrowDown,
  ArrowLeft,
  ArrowRight,
  ArrowUp,
  SlidersHorizontal,
} from "lucide-react";
import React, { useState } from "react";

type MobileKeyDockProps = {
  onSendKey: (key: string) => void;
};

export const MobileKeyDock: React.FC<MobileKeyDockProps> = ({ onSendKey }) => {
  const [isExpanded, setIsExpanded] = useState(false);
  const [ctrlLatched, setCtrlLatched] = useState(false);
  const [altLatched, setAltLatched] = useState(false);

  const triggerKey = (action: string) => {
    // Haptic vibration if supported
    if ("vibrate" in navigator) {
      try {
        navigator.vibrate(15);
      } catch {
        // ignore
      }
    }

    if (action === "ctrl") {
      setCtrlLatched(!ctrlLatched);
      return;
    }
    if (action === "alt") {
      setAltLatched(!altLatched);
      return;
    }

    let finalAction = action;
    if (ctrlLatched) {
      finalAction = `ctrl-${action}`;
      setCtrlLatched(false);
    } else if (altLatched) {
      finalAction = `alt-${action}`;
      setAltLatched(false);
    }

    onSendKey(finalAction);
  };

  return (
    <div className="w-full bg-[#12141a] border-t border-[#262833] select-none touch-manipulation z-30">
      {/* Expanded utility row */}
      {isExpanded && (
        <div className="flex gap-1.5 px-2 pt-2 pb-1 overflow-x-auto no-scrollbar text-xs font-mono">
          <KeyButton label="~" onClick={() => triggerKey("~")} />
          <KeyButton label="`" onClick={() => triggerKey("`")} />
          <KeyButton label="|" onClick={() => triggerKey("|")} />
          <KeyButton label="/" onClick={() => triggerKey("/")} />
          <KeyButton label="\" onClick={() => triggerKey("\\")} />
          <KeyButton label="-" onClick={() => triggerKey("-")} />
          <KeyButton label="_" onClick={() => triggerKey("_")} />
          <KeyButton label="=" onClick={() => triggerKey("=")} />
          <KeyButton label="PgUp" onClick={() => triggerKey("pageup")} />
          <KeyButton label="PgDn" onClick={() => triggerKey("pagedown")} />
          <KeyButton label="Home" onClick={() => triggerKey("home")} />
          <KeyButton label="End" onClick={() => triggerKey("end")} />
          <KeyButton label="Ctrl-Z" onClick={() => triggerKey("ctrl-z")} />
          <KeyButton label="Ctrl-D" onClick={() => triggerKey("ctrl-d")} />
        </div>
      )}

      {/* Primary essential row */}
      <div className="flex items-center justify-between gap-1 px-2 py-1.5 overflow-x-auto no-scrollbar">
        <div className="flex items-center gap-1.5">
          <KeyButton
            label="Ctrl"
            active={ctrlLatched}
            onClick={() => triggerKey("ctrl")}
            className="font-semibold"
          />
          <KeyButton
            label="Alt"
            active={altLatched}
            onClick={() => triggerKey("alt")}
            className="font-semibold"
          />
          <KeyButton label="Esc" onClick={() => triggerKey("esc")} />
          <KeyButton label="Tab" onClick={() => triggerKey("tab")} />
          <KeyButton
            label="Ctrl-C"
            highlight
            onClick={() => triggerKey("ctrl-c")}
            className="font-bold text-red-400 border-red-900/50 bg-red-950/30"
          />
        </div>

        <div className="flex items-center gap-1">
          <KeyButton icon={<ArrowLeft size={14} />} onClick={() => triggerKey("left")} />
          <KeyButton icon={<ArrowUp size={14} />} onClick={() => triggerKey("up")} />
          <KeyButton icon={<ArrowDown size={14} />} onClick={() => triggerKey("down")} />
          <KeyButton icon={<ArrowRight size={14} />} onClick={() => triggerKey("right")} />
          <KeyButton
            icon={<SlidersHorizontal size={13} />}
            active={isExpanded}
            onClick={() => setIsExpanded(!isExpanded)}
            title="More keys"
          />
        </div>
      </div>
    </div>
  );
};

function KeyButton({
  label,
  icon,
  active,
  highlight,
  onClick,
  className = "",
  title,
}: {
  label?: string;
  icon?: React.ReactNode;
  active?: boolean;
  highlight?: boolean;
  onClick: () => void;
  className?: string;
  title?: string;
}) {
  return (
    <button
      type="button"
      onClick={onClick}
      title={title}
      className={`min-w-[38px] h-8 px-2 flex items-center justify-center rounded border text-xs font-mono font-medium transition-all active:scale-95 ${
        active
          ? "bg-blue-600 border-blue-500 text-white shadow-sm"
          : highlight
          ? "border-[#3b4252] text-foreground bg-[#1e222d] hover:bg-[#252b38]"
          : "bg-[#1a1d26] border-[#2c3140] text-[#c9d1d9] hover:bg-[#222734] hover:text-white"
      } ${className}`}
    >
      {icon || label}
    </button>
  );
}

